36: /// 全部受控码。
37: pub const ALL: &[&str] = &[
38:     model::AUTH,
39:     model::QUOTA,
40:     model::RATE_LIMIT,
41:     model::TIMEOUT,
42:     model::NETWORK,
43:     model::SERVER,
44:     model::ENDPOINT_UNSUPPORTED,
45:     model::BAD_REQUEST,
46:     model::EMPTY_RESPONSE,
47:     model::UNKNOWN,
48:     workspace_file::TOO_LARGE,
