59: #[cfg(test)]
60: mod tests {
61:     use super::{is_known, ALL};
62:     use std::collections::BTreeSet;
63:     use std::path::{Path, PathBuf};
64: 
65:     fn collect_rs(dir: &Path, out: &mut Vec<PathBuf>) {
66:         let Ok(entries) = std::fs::read_dir(dir) else { return };
67:         for entry in entries.flatten() {
68:             let path = entry.path();
69:             if path.is_dir() {
70:                 collect_rs(&path, out);
71:             } else if path.extension().is_some_and(|ext| ext == "rs") {
72:                 out.push(path);
73:             }
74:         }
75:     }
